export const updateSupplierInvoice = defineFunction({
  name: "pennylane.update_supplier_invoice",
  connector: "pennylane",
  class: "write",
  act: true,
  description: "Correct a supplier invoice not yet validated: label, dates, invoice number, supplier, amounts, external_reference, and its lines through invoice_lines {create, update, delete} (update and delete need the line id, from list_supplier_invoice_lines). Amounts are decimal strings. The amount before tax exists at invoice level only: a line carries currency_amount (tax included) and currency_tax, plus its vat_rate. No intracom_200 code exists: for an intra-EU acquisition at 20%, ask the user which code applies, never guess. Pennylane decides whether an invoice already complete can be changed.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "required": ["invoice_id"],
    "minProperties": 2,
    "properties": {
      "invoice_id": {"type": "integer", "minimum": 1},
      "label": {"type": "string"},
      "date": {"type": "string", "format": "date", "description": "YYYY-MM-DD."},
      "deadline": {"type": "string", "format": "date", "description": "YYYY-MM-DD."},
      "invoice_number": {"type": "string", "description": "The supplier's invoice number."},
      "supplier_id": {"type": "integer", "minimum": 1},
      "currency": {"type": "string", "pattern": "^[A-Z]{3}$", "description": "ISO 4217, EUR by default."},
      "currency_amount_before_tax": {
        "type": "string",
        "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
        "description": "Decimal amount as a string, e.g. \"700.00\"."
      },
      "currency_amount": {
        "type": "string",
        "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
        "description": "Decimal amount as a string, e.g. \"700.00\"."
      },
      "currency_tax": {
        "type": "string",
        "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
        "description": "Decimal amount as a string, e.g. \"700.00\"."
      },
      "external_reference": {"type": "string"},
      "invoice_lines": {
        "type": "object",
        "additionalProperties": false,
        "minProperties": 1,
        "properties": {
          "create": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["label", "currency_amount", "currency_tax", "vat_rate"],
              "properties": {
                "label": {"type": "string"},
                "description": {"type": "string"},
                "currency_amount": {
                  "type": "string",
                  "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
                  "description": "Decimal amount as a string, e.g. \"700.00\"."
                },
                "currency_tax": {
                  "type": "string",
                  "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
                  "description": "Decimal amount as a string, e.g. \"700.00\"."
                },
                "vat_rate": {
                  "type": "string",
                  "pattern": "^[A-Za-z0-9_]+$",
                  "description": "Pennylane VAT code, never a percentage: FR_200 (20%), FR_100 (10%), FR_55 (5.5%), FR_21 (2.1%), exempt. Reverse-charge codes: intracom_21, intracom_55, intracom_85, intracom_100, extracom, crossborder, FR_85_construction, FR_100_construction, FR_200_construction."
                },
                "ledger_account_id": {"type": "integer", "minimum": 1}
              }
            }
          },
          "update": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["id"],
              "minProperties": 2,
              "properties": {
                "id": {"type": "integer", "minimum": 1},
                "label": {"type": "string"},
                "description": {"type": "string"},
                "currency_amount": {
                  "type": "string",
                  "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
                  "description": "Decimal amount as a string, e.g. \"700.00\"."
                },
                "currency_tax": {
                  "type": "string",
                  "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
                  "description": "Decimal amount as a string, e.g. \"700.00\"."
                },
                "vat_rate": {
                  "type": "string",
                  "pattern": "^[A-Za-z0-9_]+$",
                  "description": "Pennylane VAT code, never a percentage: FR_200 (20%), FR_100 (10%), FR_55 (5.5%), FR_21 (2.1%), exempt. Reverse-charge codes: intracom_21, intracom_55, intracom_85, intracom_100, extracom, crossborder, FR_85_construction, FR_100_construction, FR_200_construction."
                },
                "ledger_account_id": {"type": "integer", "minimum": 1}
              }
            }
          },
          "delete": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["id"],
              "properties": {"id": {"type": "integer", "minimum": 1}}
            }
          }
        },
        "description": "Lines to add, change or remove."
      }
    }
  },
  examples: [
    { title: "Change the VAT code of one line", input: {"invoice_id": 8001, "invoice_lines": {"update": [{"id": 9101, "vat_rate": "intracom_100"}]}} },
    { title: "Correct the invoice number and the deadline", input: {"invoice_id": 8001, "invoice_number": "FA-2026-118", "deadline": "2026-11-30"} },
  ],
  refusals: [
    { code: "supplier_invoice_not_found", when: 404, message: "No supplier invoice with this id in this Pennylane company." },
  ],
  request: {
    method: "PUT",
    path: "/supplier_invoices/{invoice_id}",
    pathParams: ["invoice_id"],
    query: {},
    body: {"label": "label", "date": "date", "deadline": "deadline", "invoice_number": "invoice_number", "supplier_id": "supplier_id", "currency": "currency", "currency_amount_before_tax": "currency_amount_before_tax", "currency_amount": "currency_amount", "currency_tax": "currency_tax", "external_reference": "external_reference", "invoice_lines": "invoice_lines"},
    headers: {},
  },
  cost: { per: "request" },
})

