export const listTransactions = defineFunction({
  name: "pennylane.list_transactions",
  connector: "pennylane",
  class: "read",
  act: false,
  description: "List bank transactions, newest first. Without a filter the whole history comes back, far beyond what an agent can read: filter on date at the source. A transaction not fully matched carries a non-zero outstanding_balance.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "filter": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": ["field", "operator", "value"],
          "properties": {
            "field": {"enum": ["id", "bank_account_id", "journal_id", "date"]},
            "operator": {"enum": ["lt", "lteq", "gt", "gteq", "eq", "not_eq", "in", "not_in", "start_with"]},
            "value": {"type": ["string", "number", "boolean", "array"], "items": {"type": ["string", "number"]}}
          },
          "allOf": [
            {
              "if": {"properties": {"operator": {"enum": ["in", "not_in"]}}},
              "then": {"properties": {"value": {"type": "array", "minItems": 1}}},
              "else": {"properties": {"value": {"type": ["string", "number", "boolean"]}}}
            }
          ]
        },
        "description": "Clauses that must all hold, each {field, operator, value}; in and not_in take a list. Fields: id, bank_account_id, journal_id (eq, not_eq, in, not_in), date (eq, not_eq, gt, lt, lteq, gteq)."
      },
      "limit": {"type": "integer", "minimum": 1, "maximum": 100, "default": 100},
      "cursor": {"type": "string", "description": "next_cursor of the previous page."},
      "all_pages": {"type": "boolean", "description": "Read the following pages too, up to max_pages (at most 5)."},
      "max_pages": {
        "type": "integer",
        "minimum": 1,
        "maximum": 5,
        "default": 5,
        "description": "Pages read when all_pages is true."
      }
    }
  },
  examples: [
    { title: "Transactions of September", input: {"filter": [{"field": "date", "operator": "gteq", "value": "2026-09-01"}, {"field": "date", "operator": "lteq", "value": "2026-09-30"}]} },
  ],
  refusals: [],
  request: {
    method: "GET",
    path: "/transactions",
    pathParams: [],
    query: {"filter": "filter", "limit": "limit", "cursor": "cursor"},
    body: {},
    headers: {},
    encode: {"filter": "json"},
  },
  pagination: { kind: "cursor", requestParam: "cursor", next: "next_cursor", more: "has_more", maxPages: 5 },
  output: { items: "items" },
  cost: { per: "request" },
})

